// Declaration
function greet(name) {
  return 'Hello, ' + name;
}

// Arrow function (same thing, shorter)
const greet = (name) => {
  return 'Hello, ' + name;
};

// Arrow with implicit return (single expression)
const greet = (name) => 'Hello, ' + name;

// Object — key/value pairs
const catch = {
  species: 'Rainbow Trout',
  length: 18,
  released: true
};

catch.species;         // 'Rainbow Trout'
catch['length'];       // 18

// Array — ordered list
const flies = ['Adams', 'Elk Hair Caddis', 'Pheasant Tail'];
flies[0];              // 'Adams'
flies.length;          // 3

async function fetchCatch(id) {
  try {
    const response = await fetch('/api/catches/' + id);
    const data = await response.json();
    return data;
  } catch (error) {
    console.error('Fetch failed:', error);
  }
}

