// Declaration style
function formatCatch(species, length) {
  return species + ' — ' + length + '"';
}

// Arrow style — same thing
const formatCatchArrow = (species, length) => {
  return species + ' — ' + length + '"';
};

// Arrow with implicit return (one-liner)
const formatCatchShort = (species, length) => species + ' — ' + length + '"';

console.log(formatCatch('Rainbow Trout', 18));
console.log(formatCatchArrow('Brown Trout', 14));
console.log(formatCatchShort('Bull Trout', 22));

const catchLog = {
  species: 'Rainbow Trout',
  length: 18,
  location: {
    river: 'Yakima',
    reach: 'Upper Canyon'
  },
  released: true,
  flies: ['Elk Hair Caddis', 'Pheasant Tail']
};

// Access a property
console.log(catchLog.species);

// Access nested
console.log(catchLog.location.river);

// Access an array inside an object
console.log(catchLog.flies[0]);

// Add a property
catchLog.waterTemp = 52;
console.log(catchLog.waterTemp);

// Check all properties
console.log(Object.keys(catchLog));

const catches = [
  { species: 'Rainbow Trout', length: 18 },
  { species: 'Brown Trout', length: 14 },
  { species: 'Bull Trout', length: 22 },
  { species: 'Rainbow Trout', length: 11 }
];

// map — transform every item, return a new array
const labels = catches.map(c => c.species + ' ' + c.length + '"');
console.log('Labels:', labels);

// filter — keep items that pass a test
const keepers = catches.filter(c => c.length >= 15);
console.log('Keepers:', keepers);

// find — first item that passes a test
const bigOne = catches.find(c => c.length > 20);
console.log('Big one:', bigOne);

// forEach — loop without producing a new array
catches.forEach(c => console.log(c.species, c.length + '"'));

// Simulated async operation (pretend this is an API call)
function delay(ms) {
  return new Promise(resolve => setTimeout(resolve, ms));
}

async function fetchSpecies(id) {
  console.log('Fetching species', id, '...');
  await delay(500); // wait 500ms
  return { id, species: 'Rainbow Trout', length: 18 };
}

async function main() {
  console.log('Start');

  const result = await fetchSpecies(1);
  console.log('Got:', result);

  // What happens WITHOUT await — the Promise object, not the data
  const missingAwait = fetchSpecies(2);
  console.log('Without await:', missingAwait);

  console.log('End');
}

main();

const shouldFail = false;

async function fetchData() {
  if (shouldFail) throw new Error('Network timeout');
  return { species: 'Brown Trout', length: 16 };
}

async function main() {
  try {
    const data = await fetchData();
    console.log('Success:', data);
  } catch (error) {
    console.error('Something went wrong:', error.message);
  } finally {
    console.log('Always runs — cleanup goes here');
  }
}

main();
